// Tower, the read-only task manager pane (crates/srv/src/server/app_api/tower_pane.rs).
// Types are generated by ts-rs.

import type { TowerPeerInfo } from "@/types/rpc/TowerPeerInfo";
import type { TowerPeersResult } from "@/types/rpc/TowerPeersResult";
import type { TowerSampleReq } from "@/types/rpc/TowerSampleReq";
import type { TowerSnapshot } from "@/types/rpc/TowerSnapshot";
import { RpcClient } from "../rpc-client";

export type { TowerHost } from "@/types/rpc/TowerHost";
export type { TowerMachine } from "@/types/rpc/TowerMachine";
export type { TowerPeerInfo } from "@/types/rpc/TowerPeerInfo";
export type { TowerProcess } from "@/types/rpc/TowerProcess";
export type { TowerProcessRole } from "@/types/rpc/TowerProcessRole";
export type { TowerSnapshot } from "@/types/rpc/TowerSnapshot";
export type { TowerTask } from "@/types/rpc/TowerTask";
export type { TowerTaskKind } from "@/types/rpc/TowerTaskKind";

export const TowerApi = {
    /** CPU and memory per task, and with `host` every process on the machine. */
    TowerSampleCommand(client: RpcClient, data: TowerSampleReq, opts?: RpcOpts): Promise<TowerSnapshot> {
        return client.rpcCall("tower.sample", data, opts);
    },
    /** The AgentMux computers this one is paired with. */
    TowerPeersCommand(client: RpcClient, opts?: RpcOpts): Promise<TowerPeersResult> {
        return client.rpcCall("tower.peers", {}, opts);
    },
    /** Pair with another AgentMux computer, from its pairing link. */
    TowerPairCommand(client: RpcClient, data: { link: string }, opts?: RpcOpts): Promise<TowerPeerInfo> {
        return client.rpcCall("tower.pair", data, opts);
    },
    /** Forget a paired computer (`TowerPeerInfo.connection`). */
    TowerForgetCommand(client: RpcClient, data: { connection: string }, opts?: RpcOpts): Promise<TowerPeersResult> {
        return client.rpcCall("tower.forget", data, opts);
    },
};
